import{_ as s,l as p,o as e,c as o,v as r,p as l,x as t,d as n,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"抓包与 Wireshark","description":"","frontmatter":{"title":"抓包与 Wireshark","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/packet-capture.md","filePath":"cs/packet-capture.md","lastUpdated":1789023840000}'),d={name:"cs/packet-capture.md"};function _(m,a,u,P,A,k){const i=p("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="抓包与-wireshark" tabindex="-1">抓包与 Wireshark <a class="header-anchor" href="#抓包与-wireshark" aria-label="Permalink to &quot;抓包与 Wireshark&quot;">​</a></h1><div class="epigraph"><p>在某点复制帧到用户态，才能对证协议叙事；GRO/TSO 与交换机镜像会改变你看见的边界。</p><footer>—— 据 RFC 919 等广播直觉；pcap 与 Wireshark 实践；IEEE 802.3 帧对照整理</footer></div><p><a href="/cs/network-measurement">上一课</a> 给汇总数字。<a href="/cs/frame-mac">帧</a> 是真正 PDU。缺口是<strong>捕获点与解释</strong>：混杂、镜像、卸载变形。本课不把 ns-3 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态机课说三次握手，线上是否如此要抓。libpcap：拷贝到 AF_PACKET 或 BPF。交换机 SPAN 看邻口。GRO 合并让「一段」其实是多 MSS。加密后只能看外层与长度——TLS 入口课的后果。DROP 在 ASIC 的包抓不到，除非镜像或 INT。</p><p>不要把抓包写成攻击嗅探教程；对象是自己的排障点。</p><p><span class="marginnote">Wireshark 是分析器。pcapng 格式。本课不教过滤器黑客用法。</span></p><h3 id="捕获点即叙事" tabindex="-1">捕获点即叙事 <a class="header-anchor" href="#捕获点即叙事" aria-label="Permalink to &quot;捕获点即叙事&quot;">​</a></h3><p>GRO/TSO 改变边界；加密挡住内层。ASIC 丢包抓不到。只在授权链路上排障。错误的点会证明错误的层。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：线 → NIC →（可选 GRO）→ pcap → 解剖。对照日志。与 PTP 硬件戳：普通 pcap 时间戳抖动大。</p>',11)),(e(),l(h,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIRE%5B%22%E4%BB%8B%E8%B4%A8%22%5D%20--%3E%20NIC%5B%22%E7%BD%91%E5%8D%A1%22%5D%0A%20%20NIC%20--%3E%20OFF%5B%22%E5%8D%B8%E8%BD%BD%E5%8F%AF%E8%83%BD%E5%8F%98%E5%BD%A2%22%5D%0A%20%20OFF%20--%3E%20PCAP%5B%22pcap%22%5D%0A%20%20PCAP%20--%3E%20DISS%5B%22%E6%8C%89%E5%B1%82%E8%A7%A3%E5%89%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LACP 哈希决定 SPAN 哪条成员。VXLAN 要解两层。QUIC 加密，只能看 UDP。权限与缓冲丢包使捕获自己丢。测量与捕获同时会改变时序（海森堡）。</p><p>法律与政策：只抓授权链路。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 eBPF 追踪的全部。ns-3 与 mininet 是下一课。后课默认：抓包验证叙事；注意卸载与捕获点。</p><p>在错误的点抓会「证明」错误的层。</p><p>上一课留下的缺口在本课收口；「抓包与 Wireshark」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/network-simulation">ns-3 与 mininet</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>捕获点决定看见哪一层。</li><li>卸载与加密改变可见性。</li><li>用来对证，不替代控制面遥测。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：pcap 实践；802.3/RFC 对照。</li></ul>',10))])}const B=s(d,[["render",_]]);export{f as __pageData,B as default};
